import{_ as s,a0 as p,w as o,s as l,ao as S,I as n,x as e,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"使用iSCSI Target創建集中式安全存儲（一） | LCTT x X-CMD","titleTemplate":false,"description":"使用iSCSI Target創建集中式安全存儲（一） | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用iSCSI Target創建集中式安全存儲（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用iSCSI Target創建集中式安全存儲（一） | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141217 Create Centralized Secure Storage using iSCSI Target on RHEL or CentOS or Fedora Part -I","title":"使用iSCSI Target創建集中式安全存儲（一）","tag":"201503","desc":""},"relativePath":"201503/20141217 Create Centralized Secure Storage using iSCSI Target on RHEL or CentOS or Fedora Part -I.md","filePath":"[post].md"}'),g={name:"201503/20141217 Create Centralized Secure Storage using iSCSI Target on RHEL or CentOS or Fedora Part -I.md"};function d(C,t,m,I,c,u){const i=p("Link");return o(),l("div",null,[t[16]||(t[16]=S(`<h1 id="使用iscsi-target創建集中式安全存儲-一" tabindex="-1">使用iSCSI Target創建集中式安全存儲（一） <a class="header-anchor" href="#使用iscsi-target創建集中式安全存儲-一" aria-label="Permalink to “使用iSCSI Target創建集中式安全存儲（一）”">​</a></h1><p><strong>iSCSI</strong> 是一種塊級別的協議，用於通過TCP/IP網絡共享<strong>原始存儲設備</strong>，可以用已經存在的IP和以太網如網卡、交換機、路由器等通過iSCSI協議共享和訪問存儲。iSCSI target是一種由遠程iSCSI服務器（target）提供的遠程硬盤。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-iSCSI-Target-in-Linux.jpg" alt="Install iSCSI Target in Linux"></p><p><em>在Linux中安裝iSCSI Target</em></p><p>我們不需要佔用很大的資源就可以為客户端提供穩定的連接和性能。iSCSI服務器稱為“Target（目標器）”，它提供服務器上的存儲共享。iSCSI客户端稱為“Initiator（發起程序）”，它訪問目標器共享的存儲。市場中有賣的用於大型存儲服務如SAN的iSCSI適配器。</p><p><strong>我們為什麼要在大型存儲領域中使用iSCSI適配器</strong></p><p>以太網適配器（NIC）被設計用於在系統、服務器和存儲設備如NAS間傳輸分組數據，它不適合在Internet中傳輸塊級數據。</p><h3 id="iscsi-target的功能" tabindex="-1">iSCSI Target的功能 <a class="header-anchor" href="#iscsi-target的功能" aria-label="Permalink to “iSCSI Target的功能”">​</a></h3><ul><li>可以在一台機器上運行幾個iSCSI 目標器</li><li>一台機器可以提供多個iSCSI 目標器用於iSCSI SAN訪問</li><li>一個目標器就是一塊存儲，並且可以通過網絡被髮起程序（客户端）訪問</li><li>把這些存儲匯聚在一起讓它們在網絡中可以訪問的是iSCSI LUN（邏輯單元號）</li><li>iSCSI支持在同一個會話中使用多個連接</li><li>iSCSI發起程序在網絡中發現目標接着用LUN驗證並登錄，這樣就可以本地訪問遠程存儲。</li><li>我們可以在本地掛載的LUN上安裝任何操作系統，就像我們安裝我們本地的操作系統一樣。</li></ul><h3 id="為什麼需要iscsi" tabindex="-1">為什麼需要iSCSI？ <a class="header-anchor" href="#為什麼需要iscsi" aria-label="Permalink to “為什麼需要iSCSI？”">​</a></h3><p>在虛擬化中，我們需要存儲擁有高度的冗餘性、穩定性，iSCSI以低成本的方式提供了這些特性。與使用光纖通道的SAN比起來，我們可以使用已經存在的設備比如NIC、以太網交換機等建造一個低成本的SAN。</p><p>現在我開始使用iSCSI 目標器安裝並配置安全存儲。本篇中，我們遵循下面的步驟：</p><ul><li>我們需要隔離一個系統來設置iSCSI Target服務器和發起程序（客户端）。</li><li>在大型存儲環境中可以添加多個硬盤，但是這裏我們除了基本的安裝盤之外只使用了一個額外的驅動器。</li><li>這裏我們只使用了2塊硬盤，一個用於基本的服務器安裝，另外一個用於存儲（LUN），這個我們會在這個系列的第二篇描述。</li></ul><h4 id="主服務器設置" tabindex="-1">主服務器設置 <a class="header-anchor" href="#主服務器設置" aria-label="Permalink to “主服務器設置”">​</a></h4><ul><li>操作系統 – CentOS 6.5 (Final)</li><li>iSCSI 目標器 IP – 192.168.0.200</li><li>使用的端口 : TCP 860, 3260</li><li>配置文件 : /etc/tgt/targets.conf</li></ul><h3 id="安裝-iscsi-target" tabindex="-1">安裝 iSCSI Target <a class="header-anchor" href="#安裝-iscsi-target" aria-label="Permalink to “安裝 iSCSI Target”">​</a></h3><p>打開終端並使用yum命令來搜索需要在iscsi 目標器上安裝的包名。</p><pre><code># yum search iscsi
</code></pre><h4 id="輸出示例" tabindex="-1">輸出示例 <a class="header-anchor" href="#輸出示例" aria-label="Permalink to “輸出示例”">​</a></h4><pre><code>========================== N/S matched: iscsi =======================
iscsi-initiator-utils.x86_64 : iSCSI daemon and utility programs
iscsi-initiator-utils-devel.x86_64 : Development files for iscsi-initiator-utils
lsscsi.x86_64 : List SCSI devices (or hosts) and associated information
scsi-target-utils.x86_64 : The SCSI target daemon and utility programs
</code></pre><p>你會的到上面的那些結果，選擇<strong>Target</strong>包來安裝。</p><pre><code># yum install scsi-target-utils -y
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-iSCSI-in-Linux.jpg" alt="Install iSCSI Utils"></p><p><em>安裝iSCSI工具</em></p><p>列出安裝的包裏面的內容來了解默認的配置、服務和man頁面的位置。</p><pre><code># rpm -ql scsi-target-utils.x86_64
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-All-ISCSI-Files.jpg" alt="List All iSCSI Files"></p><p><em>列出所有的iSCSI包裏面的文件</em></p><p>讓我們啓動iSCSI服務，並檢查服務運行的狀態，iSCSI的服務名是<strong>tgtd</strong>。</p><pre><code># /etc/init.d/tgtd start
# /etc/init.d/tgtd status
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Start-iSCSI-Service.jpg" alt="Start iSCSI Service"></p><p><em>啓動iSCSI服務</em></p><p>現在我們需要配置開機自動啓動。</p><pre><code># chkconfig tgtd on
</code></pre><p>現在驗證tgtd服務的運行級別是否配置正確。</p><pre><code># chkconfig --list tgtd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Enable-iSCSI-on-Startup.jpg" alt="Enable iSCSI on Startup"></p><p><em>開機啓動iSCSI</em></p><p>現在使用<strong>tgtadm</strong>來列出在我們的服務器上已經配置了哪些目標器和LUN。</p><pre><code># tgtadm --mode target --op show
</code></pre><p><strong>tgtd</strong>已經安裝並在運行了，但是上面的命令沒有<strong>輸出</strong>因為我們還沒有在目標器上定義LUN。要查看手冊，可以運行‘<strong>man</strong>‘命令。</p><pre><code># man tgtadm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/iSCSI-Man-Pages.jpg" alt="iSCSI Man Pages"></p><p><em>iSCSI Man 頁面</em></p><p>如果你的target服務器上有iptable的話，那麼我們需要為iSCSI添加iptable規則。首先使用netstat命令找出iscsi target的端口號，target總是監聽TCP端口3260。</p><pre><code># netstat -tulnp | grep tgtd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Find-iSCSI-Port.jpg" alt="Find iSCSI Port"></p><p><em>找出iSCSI端口</em></p><p>下面加入如下規則讓iptable允許廣播iSCSI 目標器發現包。</p><pre><code># iptables -A INPUT -i eth0 -p tcp --dport 860 -m state --state NEW,ESTABLISHED -j ACCEPT
# iptables -A INPUT -i eth0 -p tcp --dport 3260 -m state --state NEW,ESTABLISHED -j ACCEPT
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Open-iSCSI-Ports.jpg" alt="Open iSCSI Ports"></p><p><em>打開iSCSI端口</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Add-iSCSI-Ports-to-Iptables.jpg" alt="Add iSCSI Ports to Iptables"></p><p><em>添加iSCSI端口到iptable中</em></p><p><strong>注意</strong>： 規則可能根據你的 <strong>默認鏈策略</strong>而不同。接着保存iptable並重啓該服務。</p><pre><code># iptables-save
# /etc/init.d/iptables restart
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Restart-iptables.jpg" alt="Restart iptables"></p><p><em>重啓iptable</em></p><p>現在我們已經部署了一個目標器來共享LUN給通過TCP/IP認證的發起程序。這也適用於從小到大規模的生產環境。</p>`,59)),n("p",null,[t[1]||(t[1]=e("在我的下篇文章中，我會展示如何",-1)),r(i,{href:"http://www.tecmint.com/create-luns-using-lvm-in-iscsi-target/"},{default:a(()=>[...t[0]||(t[0]=[e("在目標器中使用LVM創建LUN",-1)])]),_:1}),t[2]||(t[2]=e("，並且如何在客户端中共享LUN，不要忘記留下有價值的評論。",-1))]),t[17]||(t[17]=n("hr",null,null,-1)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),r(i,{href:"http://www.tecmint.com/create-centralized-secure-storage-using-iscsi-targetin-linux/"},{default:a(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/create-centralized-secure-storage-using-iscsi-targetin-linux/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("作者：",-1)),r(i,{href:"http://www.tecmint.com/author/babinlonston/"},{default:a(()=>[...t[5]||(t[5]=[e("Babin Lonston",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),r(i,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const f=s(g,[["render",d]]);export{h as __pageData,f as default};
